#pragma once

// Static description of the 50 Twilight Princess HD stamps.
//
// Stamp index 0-49 == the HD save bit == position in the HD stamp book. The table itself lives in
// stamp_table.inc, generated by tools/gen_stamp_table.py from research/stamps_all50.csv and
// research/stamp_chests.csv (data facts only: ids, flags, stage and room numbers; hints are this mod's own
// wording). The stamps' names are HD text (zel_00 2890 + index): they are read at run time from the generated
// res/stamps/hdtext/messages.bin (hdtext::stamp_name), never stored here. The 7 HD-only chests' stage records
// are read at run time from the generated res/stamps/stamps/hd_chests.bin (items.cpp), never stored here.

#include <array>
#include <cstddef>
#include <cstdint>
#include <cstring>

namespace hdstamps {

inline constexpr int kStampCount = 50;
inline constexpr int kTwiliMidnaIndex = 49;
inline constexpr uint64_t kAllStampsMask = (uint64_t{1} << kStampCount) - 1;
inline constexpr uint64_t kTwiliMidnaBit = uint64_t{1} << kTwiliMidnaIndex;

enum class StampSource : uint8_t {
    Chest,     // GC chest whose content HD changed to the stamp (39 chests)
    HdChest,   // chest that only exists in HD; added with StageService::add_actor (7 chests)
    Gengle,    // Jovani's cat, after all 60 Poe souls
    Agitha,    // Agitha, after a golden bug hand-in
    MaloMart,  // Castle Town Malo Mart
    Automatic, // Twili Midna: granted once the other 49 are owned
};

struct StampDef {
    uint8_t index;    // 0-49
    uint8_t item;     // HD item id (NOENTRY on GC)
    StampSource source;
    const char* stage; // chest stage (nullptr for non-chest stamps)
    int8_t room;       // chest room
    int8_t layer;      // chest layer; -1 = not layered / every layer
    int8_t tboxNo;     // chest-opened bit (== chest save bit), -1 for non-chest
    int8_t saveTbl;    // dSv_save_c::mSave index of the chest's stage, -1 for non-chest
    uint8_t gcItem;    // vanilla GC item of the re-stocked chest (0xFF for HD-only/non-chest)
    const char* hint; // where to look, own wording
};

// An HD-only chest's stage record (TRES, stage_actor_data_class: 0x20 bytes big-endian: name[8], parameters,
// position, angle, set id), as the mod's converter copies it from the player's own HD copy into
// res/stamps/stamps/hd_chests.bin. True when it is this stamp's chest: a "tbox..." actor whose chest number
// (parameters bits 6-11) and item (the high byte of angle z) are the table's.
inline bool hd_chest_record_matches(const StampDef& def, const uint8_t* rec) {
    if (rec == nullptr || std::memcmp(rec, "tbox", 4) != 0) {
        return false;
    }
    const uint32_t params = (uint32_t{rec[8]} << 24) | (uint32_t{rec[9]} << 16) | (uint32_t{rec[10]} << 8) |
        uint32_t{rec[11]};
    return ((params >> 6) & 0x3F) == static_cast<uint32_t>(def.tboxNo) && rec[0x1C] == def.item;
}

#include "stamp_table.inc"

static_assert(sizeof(kStamps) / sizeof(kStamps[0]) == kStampCount);

constexpr bool stamp_table_is_consistent() {
    for (int i = 0; i < kStampCount; ++i) {
        if (kStamps[i].index != i) {
            return false;
        }
        for (int j = i + 1; j < kStampCount; ++j) {
            if (kStamps[i].item == kStamps[j].item) {
                return false;
            }
        }
    }
    for (int i = 0; i < kStampCount; ++i) {
        const StampDef& d = kStamps[i];
        if (d.source == StampSource::HdChest && (d.stage == nullptr || d.room < 0 || d.tboxNo < 0)) {
            return false;
        }
    }
    return kStamps[kTwiliMidnaIndex].source == StampSource::Automatic;
}
static_assert(stamp_table_is_consistent(), "stamp_table.inc is inconsistent; regenerate it");

constexpr uint64_t stamp_bit(int index) {
    return uint64_t{1} << index;
}

// Returns the stamp index for an item id, or -1.
constexpr int stamp_index_for_item(uint8_t item) {
    for (int i = 0; i < kStampCount; ++i) {
        if (kStamps[i].item == item) {
            return i;
        }
    }
    return -1;
}

// HD item ids of the stamps that are not in chests, and their table indices. The indices are
// used as array subscripts and shift amounts, so a regenerated table without one of these items
// must fail to compile instead of producing kStamps[-1] / (1 << -1).
inline constexpr uint8_t kGengleStampItem = 0x98;   // Rupee stamp
inline constexpr uint8_t kAgithaStampItem = 0xBD;   // Agitha stamp
inline constexpr uint8_t kMaloMartStampItem = 0xBE; // Malo Mart stamp
inline constexpr int kGengleStampIndex = stamp_index_for_item(kGengleStampItem);
inline constexpr int kAgithaStampIndex = stamp_index_for_item(kAgithaStampItem);
inline constexpr int kMaloMartStampIndex = stamp_index_for_item(kMaloMartStampItem);
static_assert(kGengleStampIndex >= 0 && kStamps[kGengleStampIndex].source == StampSource::Gengle,
    "stamp_table.inc: the Rupee (Gengle) stamp is missing; regenerate it");
static_assert(kAgithaStampIndex >= 0 && kStamps[kAgithaStampIndex].source == StampSource::Agitha,
    "stamp_table.inc: the Agitha stamp is missing; regenerate it");
static_assert(kMaloMartStampIndex >= 0 && kStamps[kMaloMartStampIndex].source == StampSource::MaloMart,
    "stamp_table.inc: the Malo Mart stamp is missing; regenerate it");

// Message id of the item-get text: d_a_alink_demo.inc uses item + 0x65 in group 0 (zel_00).
constexpr uint16_t get_message_id(uint8_t item) {
    return static_cast<uint16_t>(item + 0x65);
}

} // namespace hdstamps
